1	import { useId } from "react";
2	
3	/**
4	 * Choice — NovaKit Lite
5	 * One component for a checkbox or a radio: a native <input> inside a <label>.
6	 * Types: checkbox | radio
7	 * States: unchecked, checked, focus-visible, disabled (with a visible reason)
8	 *
9	 * - Controlled only. It never defaults to checked: pass `checked` and `onChange`.
10	 * - The whole row is the tap target, at least 44px tall.
11	 * - The accessible name is the label only. The description and the disabled reason
12	 *   are read as descriptions (aria-describedby), so they're heard but not repeated.
13	 * - Any other props (aria-*, required, form…) go to the <input>.
14	 *
15	 * Radio groups: the caller wraps the options in a <fieldset> with a <legend>
16	 * that names the choice, and gives every option the same `name`. For example:
17	 *
18	 *   <fieldset>
19	 *     <legend>How much do you need?</legend>
20	 *     <Choice type="radio" name="amount" value="5000" checked={…} onChange={…} label="Rs 5,000" />
21	 *     <Choice type="radio" name="amount" value="10000" checked={…} onChange={…} label="Rs 10,000" />
22	 *   </fieldset>
23	 */
24	export default function Choice({
25	  type = "checkbox",
26	  name,
27	  value,
28	  checked = false,
29	  onChange,
30	  label,
31	  description = null,
32	  disabled = false,
33	  disabledReason = null,
34	  id,
35	  ...rest
36	}) {
37	  const autoId = useId();
38	  const inputId = id ?? `choice-${autoId}`;
39	  const labelId = `${inputId}-label`;
40	  const descriptionId = description ? `${inputId}-description` : null;
41	  const reasonId = disabled && disabledReason ? `${inputId}-reason` : null;
42	  const describedBy =
43	    [rest["aria-describedby"], descriptionId, reasonId].filter(Boolean).join(" ") || undefined;
44	
45	  return (
46	    <label
47	      htmlFor={inputId}
48	      className={
49	        "flex items-start gap-3 min-h-11 py-2.5 " +
50	        (disabled ? "cursor-not-allowed" : "cursor-pointer")
51	      }
52	    >
53	      <input
54	        {...rest}
55	        id={inputId}
56	        type={type}
57	        name={name}
58	        value={value}
59	        checked={checked === true}
60	        onChange={onChange}
61	        disabled={disabled}
62	        aria-labelledby={labelId}
63	        aria-describedby={describedBy}
