// ---- Formatting dates and times --------------------------------------------

export function formatDate(date) {
  if (date == null) return null;
  const [, m, d] = date.split("-").map(Number);
  return `${d} ${MONTHS[m - 1]}`;
}

export function formatTime(time) {
  if (time == null) return null;
  const [h, min] = time.split(":").map(Number);
  const suffix = h < 12 ? "am" : "pm";
  const hour = h % 12 || 12;
  return min ? `${hour}:${pad(min)}${suffix}` : `${hour}${suffix}`;
}

// ---- Reviewer scenarios ----------------------------------------------------

// The date each state is viewed on. Everything else is 7 Jul.
const SCENARIO_DATES = {
  S10: "2026-07-25", // reminder before the due date
  S11: "2026-07-28", // not collected on payday
  S12: "2026-08-02", // late, 5 days
  S13: "2026-08-20", // notice before default
};

// Inputs for each "not collected" cause. Scenario data only; screens don't show these.
const NOT_COLLECTED_INPUTS = {
  salary_not_arrived: { salary_landed: false, salary_amount: null, balance: 1800, salary_destination: "novapay" },
  salary_short: { salary_landed: true, salary_amount: 9000, balance: 9600, salary_destination: "novapay" },
  balance_dropped: { salary_landed: true, salary_amount: 68000, balance: 6500, salary_destination: "novapay" },
  salary_moved_to_bank: { salary_landed: false, salary_amount: null, balance: 1800, salary_destination: "bank" },
};

export const SCENARIO_IDS = ["S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9", "S10", "S11", "S12", "S13"];

export function scenario(id, { reason = "salary_not_arrived" } = {}) {
  if (!SCENARIO_IDS.includes(id)) throw new Error(`Unknown scenario ${id}`);
  const today = SCENARIO_DATES[id] ?? PROTOTYPE_TODAY;
  if (id === "S2") {
    const B = PERSONAS.B;
    return { id, persona: B, today, offer: getOffer(B, today), terms: null, advance: null };
  }

  const A = PERSONAS.A;
  const offer = getOffer(A, PROTOTYPE_TODAY);
  const terms = getTerms(A, 10000, PROTOTYPE_TODAY);
  const base = { id, persona: A, today, offer, terms, advance: null };
  if (["S1", "S3", "S4", "S5", "S6"].includes(id)) return base;
  if (id === "S7") return { ...base, terms: reducePayout(terms) };

  let advance = acceptTerms(terms, { permission_granted: true }, PROTOTYPE_TODAY);
  if (["S11", "S12", "S13"].includes(id)) {
    advance = collectionOutcome(advance, {
      date: advance.due_date,
      time: COLLECTION_TIME,
      ...NOT_COLLECTED_INPUTS[reason],
    });
  }
  return { ...base, advance };
}

import { useState } from "react";
import {
  AppBar,
  Card,
  ListRow,
  Button,
  AmountText,
  Toast,
} from "./novakit";

/**
 * Starter app — a minimal NovaPay home screen rendered in a mobile frame.
 *
 * This is your canvas. The salary-advance experience (offer → terms →
 * accept, plus the not-good path) does NOT exist yet — that's what you'll
 * build. Add screens/routing however you like; everything should be built
 * from NovaKit Lite (./novakit). See README.md.
 */
export default function App() {
  const [toast, setToast] = useState(false);

  function handleSeeOffer() {
    // TODO (candidate): this is where the salary-advance flow begins.
    setToast(true);
    setTimeout(() => setToast(false), 2200);
  }

  // The sticky action area at the bottom of the frame. A screen puts its main action
  // here so it stays visible while the content scrolls. Nothing is shown when empty.
  const actions = null;

  return (
    <div className="min-h-screen w-full flex justify-center items-start gap-6 py-6">
      {/* Reviewer controls (src/review/) go beside the frame, never inside it. */}

      {/* Mobile frame: a fixed 390×844 device. The AppBar and action area stay put; main scrolls. */}
      <div className="relative w-[390px] h-[844px] shrink-0 flex flex-col bg-neutral-50 rounded-[28px] shadow-xl overflow-hidden border border-neutral-300">
        <AppBar title="NovaPay" />

        <main className="phone-scroll flex-1 min-h-0 overflow-y-auto p-4 space-y-4">
          <Card>
            <div className="text-caption text-neutral-500">Available balance</div>
            <div className="mt-1">
              <AmountText amount={4250} size="display" />
            </div>
          </Card>

          <Card className="space-y-3">
            <div>
              <div className="text-title text-neutral-900">Need cash before payday?</div>
              <div className="text-body text-neutral-700 mt-1">
                You may qualify for a NovaPay salary advance.
              </div>
            </div>
            <Button size="lg" onClick={handleSeeOffer}>
              See your offer
            </Button>
          </Card>

          <Card>
            <div className="text-caption text-neutral-500 mb-1">Recent activity</div>
            <ListRow
              icon="↑"
              title="Sent to Ahmed K."
              subtitle="Today, 2:14 PM"
              trailing={<AmountText amount={1500} size="body" />}
            />
            <ListRow
              icon="↓"
              title="Salary credited"
              subtitle="28 Jun"
              trailing={<AmountText amount={68000} size="body" />}
            />
            <ListRow
              icon="↑"
              title="Mobile top-up"
              subtitle="27 Jun"
              trailing={<AmountText amount={500} size="body" />}
            />
          </Card>
        </main>

        {actions ? (
          <footer className="shrink-0 bg-white border-t border-neutral-200 p-4 space-y-3">{actions}</footer>
        ) : null}

        <Toast open={toast} message="TODO: build the salary-advance flow" />
      </div>
    </div>
  );
}

/**
 * Card — NovaKit Lite
 * A surface container for grouping content.
 * Tones: default | attention | danger
 *
 * - attention is for a person's status (late, notice before default).
 * - danger is only for a failed event ("We couldn't collect on 28 Jul", a network
 *   failure), never for a person's status.
 * - Both are a soft background with inherited dark text (neutral-900). No icons,
 *   no solid fills. Every tone's border is as faint as the default card's edge.
 * - Card adds no role by itself. A screen that shows a failure passes
 *   role="alert" (or aria-live), which goes to the <div> with any other props.
 */
export default function Card({ children, tone = "default", className = "", ...rest }) {
  const tones = {
    default: "bg-white border-neutral-200",
    attention: "bg-attention-50 border-attention-100",
    danger: "bg-danger-50 border-neutral-200",
  };
  return (
    <div
      {...rest}
      className={`rounded-lg border shadow-card p-4 ${tones[tone] || tones.default} ${className}`}
    >
      {children}
    </div>
  );
}

