// Reads Chromium's real accessibility tree for S3 over the DevTools protocol.
// Usage: node axnames.mjs <edge.exe> <profile-dir> <url>
import { spawn } from "node:child_process";

const [edge, profile, url] = process.argv.slice(2);
const port = 9333;
const proc = spawn(edge, [
  "--headless=new", `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`,
  "--no-first-run", "--window-size=390,844", "about:blank",
], { stdio: "ignore" });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 40; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(250); }
}
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0;
const pending = new Map();
ws.addEventListener("message", (e) => {
  const msg = JSON.parse(e.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
const send = (method, params = {}) => new Promise((r) => { const n = ++id; pending.set(n, r); ws.send(JSON.stringify({ id: n, method, params })); });

await send("Page.enable");
await send("Accessibility.enable");
await send("Page.navigate", { url });
await sleep(4000);
await send("Runtime.evaluate", { expression: `[...document.querySelectorAll('button')].find(b => b.textContent.includes('See your offer')).click()` });
await sleep(800);
const { result } = await send("Accessibility.getFullAXTree");
for (const n of result.nodes) {
  const role = n.role?.value;
  if (!["radio", "button", "group", "heading", "status"].includes(role)) continue;
  const props = Object.fromEntries((n.properties ?? []).map((p) => [p.name, p.value?.value]));
  console.log(JSON.stringify({
    role,
    name: n.name?.value ?? "",
    description: n.description?.value ?? "",
    ...(props.disabled ? { disabled: true } : {}),
    ...(props.focusable ? { focusable: true } : {}),
  }));
}
ws.close();
proc.kill();
process.exit(0);

