await tick(200);
const main = frame.querySelector('main');
const card = main.querySelector('h2').closest('div.rounded-lg');
const original = card.innerHTML;
const b = (t) => `<span class="font-semibold">${t}</span>`;
const H = (t) => `<h2 class="text-body font-semibold text-neutral-900">${t}</h2>`;
const P = (t) => `<p class="text-body text-neutral-900">${t}</p>`;
const candidates = {
  current: original,
  O1_heading_carries_loan: H('A short-term loan, repaid on payday') + P(`The fee is ${b('3%')}, charged once. If you accept, we take the full amount from your NovaPay wallet automatically at ${b('6pm')} on ${b('28 Jul')}, once your salary arrives.`),
  O2_no_heading_full: P(`A salary advance is a short-term loan. The fee is ${b('3%')}, charged once. If you accept, we take the full amount from your NovaPay wallet automatically at ${b('6pm')} on payday, once your salary arrives.`),
