};
const out = {};
for (const [k, html] of Object.entries(candidates)) {
  card.innerHTML = html;
  await tick(100);
  const fold = main.getBoundingClientRect().bottom;
  const rows = [...main.querySelectorAll('input[type=radio]')].map(r => r.closest('label').getBoundingClientRect());
  const lines = [...card.querySelectorAll('p,h2')].map(e => Math.round(e.getBoundingClientRect().height / 22));
  out[k] = { cardH: Math.round(card.getBoundingClientRect().height), lines, rs5000: rows[0].bottom <= fold ? 'fully visible' : `cut by ${Math.round(rows[0].bottom - fold)}px`, rs10000: rows[1].bottom <= fold ? 'fully visible' : rows[1].top < fold ? `starts, cut by ${Math.round(rows[1].bottom - fold)}px` : 'below', rs15000: rows[2].bottom <= fold ? 'fully visible' : rows[2].top < fold ? `starts, cut by ${Math.round(rows[2].bottom - fold)}px` : 'below' };
}
card.innerHTML = original;
out

