const main = document.querySelector('main');
const card = main.querySelector('h2').closest('div.rounded-lg');
const original = card.innerHTML;
const b = (t) => `<span class="font-semibold">${t}</span>`;
const P = (t) => `<p class="text-body text-neutral-900">${t}</p>`;
const candidates = {
  O3: `A short-term loan with a ${b('3%')} fee, charged once. If you accept, we take the full amount from your wallet automatically at ${b('6pm')} on payday, once your salary arrives.`,
