  O6_keeps_automatically: `A short-term loan, ${b('3%')} fee charged once. If you accept, we take it from your wallet automatically at ${b('6pm')} on payday, once salary arrives.`,
  O7_split_lines: `A short-term loan. ${b('3%')} fee, charged once.<br>If you accept, we take it from your wallet automatically at ${b('6pm')} on payday, once your salary arrives.`,
};
const out = {};
for (const [k, t] of Object.entries(candidates)) {
  card.innerHTML = P(t);
