          onAmountChange={setAmount}
          onContinue={() => go("terms")}
          onLeave={leaveToHome}
        />
      ) : null}

      {current === "terms" ? <TermsPlaceholder Frame={PhoneFrame} onBack={() => go("chooseAmount")} /> : null}
    </div>
