      </ul>
    </BottomSheet>
  );

  const appBar = reduced ? (
    <AppBar title="Check the new amount" />
  ) : (
    <AppBar
      title="Review and accept"
      onBack={processing ? null : onChangeAmount}
      backLabel="Back to amounts"
    />
  );

  const actions = (
    <>
      {/* Next to the button, so it's seen where the tap happened. */}
      <div>
        <div role="status" className={message ? "text-body text-neutral-900 pb-3" : ""}>
          {message}
        </div>
        {/* One line: the repayment and its date are on the screen, above. */}
        <Button onClick={handleAccept} loading={processing} loadingLabel={PROCESSING_LABEL}>
          Accept {formatAmount(terms.disbursed_amount)}
        </Button>
      </div>
      {processing ? null : reduced ? (
        <Button variant="secondary" onClick={onLeave}>
          No thanks
        </Button>
      ) : (
        <div className="grid grid-cols-2 gap-3">
          <Button variant="secondary" onClick={onChangeAmount}>
            Change amount
          </Button>
          <Button variant="secondary" onClick={onLeave}>
            Back to home
          </Button>
        </div>
      )}
    </>
  );

  return (
    <Frame
      title={reduced ? "Check the new amount: NovaPay" : "Review and accept: NovaPay"}
      sheet={lateSheet}
      appBar={appBar}
      actions={actions}
    >
      {/* While processing, nothing here can be changed or reached. */}
      <div className="space-y-4" inert={processing ? "" : undefined} aria-busy={processing || undefined}>
        {failed ? (
          <Card tone="danger" role="alert" className="space-y-2">
            <div ref={failureRef}>
              <p className="text-body font-semibold text-neutral-900">We couldn't confirm your advance</p>
              <p className="text-body text-neutral-900 mt-1">
                Nothing was sent to your wallet and nothing was charged. Check your connection, then try again.
              </p>
            </div>
            <button
              ref={retryRef}
              type="button"
              onClick={handleAccept}
              className="sr-only"
              tabIndex={-1}
              aria-hidden="true"
            />
            <Button variant="secondary" onClick={handleAccept}>
              Try again
            </Button>
          </Card>
        ) : null}

        {reduced ? (
          <ReducedSummary terms={terms} due={due} time={time} />
        ) : (
          <Card>
            <h2 className="text-body font-semibold text-neutral-900">Your advance</h2>
            <div className="mt-1">
              <ListRow
                wrap
                title="You get"
                subtitle="Paid into your NovaPay wallet"
                trailing={<AmountText amount={terms.disbursed_amount} size="body" className="font-semibold" />}
              />
              <ListRow
                wrap
                title="Fee"
                subtitle={`${FEE_PERCENT}%, charged once`}
                trailing={<AmountText amount={terms.fee} size="body" className="font-semibold" />}
              />
              <ListRow
                wrap
                title={<span className="font-semibold">You repay on {due}</span>}
                subtitle={`At ${time} from your NovaPay wallet, once your salary arrives`}
                trailing={<AmountText amount={terms.total} size="body" className="font-semibold" />}
              />
            </div>
            <p className="text-caption text-neutral-700 mt-2">
              If we can only pay a lower amount, we'll show you the new terms and ask you again before paying
              anything.
            </p>
          </Card>
        )}

        <Card className="space-y-2">
          <p className="text-body text-neutral-900">
            If we can't take it on {due}, we'll tell you at {time}. If your salary is late, we'll try again when it
            arrives.
          </p>
          <button
            type="button"
            aria-haspopup="dialog"
            onClick={() => setLateOpen(true)}
            className="inline-flex items-center min-h-11 rounded-sm text-body font-semibold text-brand focus:outline-none focus-visible:ring-2 focus-visible:ring-brand focus-visible:ring-offset-2"
          >
            What happens if it's late
          </button>
        </Card>

        <Card>
          <Choice
            id={permissionId}
            type="checkbox"
            name="collection-permission"
            checked={permission}
            onChange={handlePermission}
            label={
              reduced
                ? "I allow NovaPay to take the new repayment automatically."
                : "I allow NovaPay to take the repayment above automatically."
            }
            description={`This ends automatically when it's repaid, or on ${until} at the latest.`}
          />
        </Card>
      </div>
    </Frame>
  );
}

// S7: what changed, in plain words, then old and new side by side.
function ReducedSummary({ terms, due, time }) {
  const before = terms.reduced_from;
  const rows = [
    { label: "You get", was: before.disbursed_amount, now: terms.disbursed_amount },
    { label: "Fee", was: before.fee, now: terms.fee },
    { label: "You repay", was: before.total, now: terms.total },
  ];
  const when = `${due} at ${time}`;
  return (
    <>
      <Card className="space-y-2">
        <h2 className="text-title text-neutral-900">
          We can offer {formatAmount(terms.disbursed_amount)}, not {formatAmount(before.disbursed_amount)}
        </h2>
        <p className="text-body text-neutral-900">
          After our final checks, {formatAmount(before.disbursed_amount)} isn't available. Nothing has been sent or
          charged. If {formatAmount(terms.disbursed_amount)} works for you, accept it below. If not, you don't need to
          do anything.
        </p>
      </Card>

      <Card>
        <table className="w-full text-body">
          <caption className="sr-only">What you asked for and what we can offer</caption>
          <thead>
            <tr className="text-caption text-neutral-700">
              <th scope="col" className="text-left font-normal pb-2">
                <span className="sr-only">Item</span>
              </th>
              <th scope="col" className="text-right font-normal pb-2">You asked for</th>
              <th scope="col" className="text-right font-semibold text-neutral-900 pb-2">We can offer</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-neutral-300">
            {rows.map((r) => (
              <tr key={r.label}>
                <th scope="row" className="text-left font-normal text-neutral-900 py-2">{r.label}</th>
                <td className="text-right text-neutral-700 py-2">
                  <AmountText amount={r.was} size="body" />
                </td>
                <td className="text-right text-neutral-900 font-semibold py-2">
                  <AmountText amount={r.now} size="body" />
                </td>
              </tr>
            ))}
            <tr>
              <th scope="row" className="text-left font-normal text-neutral-900 py-2">On</th>
              <td className="text-right text-neutral-700 py-2">{when}</td>
              <td className="text-right text-neutral-900 font-semibold py-2">{when}</td>
            </tr>
          </tbody>
        </table>
      </Card>
    </>
  );
}

