const tick = (ms = 250) => new Promise(r => setTimeout(r, ms));
const waitFor = async (fn, ms = 4000) => { const end = Date.now() + ms; while (Date.now() < end) { const v = fn(); if (v) return v; await tick(100); } return null; };
await waitFor(() => document.querySelector('h1'), 12000);
const btn = (t) => [...document.querySelectorAll('button')].find(b => b.textContent.includes(t));
