document.querySelector('input[value="10000"]').click(); await tick();
btn('Review terms').click(); await tick();
document.querySelector('input[type=checkbox]').click(); await tick();
btn('Accept').click();
const s7 = await waitFor(() => btn('Accept Rs 5,000'));
const out = {};
for (const [label, el] of [['S7', s7], ['S4', null]]) {
  if (!el) continue;
  el.click(); await tick(500);
  const main = document.querySelector('main');
  const r = document.querySelector('input[type=checkbox]').closest('label').getBoundingClientRect(), m = main.getBoundingClientRect();
  out[label] = { rowInView: r.top >= m.top && r.bottom <= m.bottom, focused: document.activeElement.type };
}
