const tick = (ms = 250) => new Promise(r => setTimeout(r, ms));
const waitFor = async (fn, ms = 10000) => { const end = Date.now() + ms; while (Date.now() < end) { const v = fn(); if (v) return v; await tick(100); } return null; };
await waitFor(() => document.querySelector('h1'), 12000);
const btn = (t) => [...document.querySelectorAll('button')].find(b => b.textContent.startsWith(t));
const frame = document.querySelector('header').parentElement.getBoundingClientRect();
const vw = document.documentElement.clientWidth;
const aside = document.querySelector('aside').getBoundingClientRect();
const out = { frameCentreOffset: Math.round(frame.left + frame.width / 2 - vw / 2), asideRightOfFrame: aside.left >= frame.right, firstTabStopInPhone: null };
// tab order: first focusable in document
const focusables = [...document.querySelectorAll('button, input')].filter(el => !el.disabled);
out.firstTabStopInPhone = !focusables[0].closest('aside');
// S7
document.querySelector('input[name="accept-outcome"][value="reduced"]').click(); await tick();
btn('See amounts and costs').click(); await tick();
document.querySelector('input[value="10000"]').click(); await tick();
btn('Review terms').click(); await tick();
document.querySelector('main input[type=checkbox]').click(); await tick();
btn('Accept').click();
await waitFor(() => document.title.startsWith('Check the new amount'));
out.s7 = document.querySelector('main').innerText.split('\n').filter(Boolean).slice(0, 14);
// network failure fails again on a second run
document.querySelector('input[name="accept-outcome"][value="network"]').click(); await tick();
const runOnce = async () => {
  btn('See amounts and costs').click(); await tick();
  document.querySelector('input[value="5000"]').click(); await tick();
  btn('Review terms').click(); await tick();
  document.querySelector('main input[type=checkbox]').click(); await tick();
  btn('Accept').click();
  return await waitFor(() => document.querySelector('[role=alert]') || (document.title.startsWith('Receipt') && 'receipt'));
};
btn('No thanks').click(); await tick();
const r1 = await runOnce(); out.run1 = r1 === 'receipt' ? 'receipt' : 'failed';
btn('Try again').click(); await waitFor(() => document.title.startsWith('Receipt')); btn('Done').click(); await tick();
const r2 = await runOnce(); out.run2 = r2 === 'receipt' ? 'receipt' : 'failed';
out.failureText = document.querySelector('[role=alert]')?.innerText.replace(/\n+/g, ' | ');
out

