const tick = (ms = 250) => new Promise(r => setTimeout(r, ms));
const waitFor = async (fn, ms = 10000) => { const end = Date.now() + ms; while (Date.now() < end) { const v = fn(); if (v) return v; await tick(100); } return null; };
await waitFor(() => document.querySelector('h1'), 12000);
const btn = (t) => [...document.querySelectorAll('button')].find(b => b.textContent.startsWith(t));
const mainText = () => document.querySelector('main').innerText.split('\n').filter(Boolean);
const out = {};
btn('See amounts and costs').click(); await tick();
document.querySelector('input[value="10000"]').click(); await tick();
btn('Review terms').click(); await tick();
out.s4Rows = mainText().slice(0, 10);
document.querySelector('main input[type=checkbox]').click(); await tick();
btn('Accept').click();
await waitFor(() => document.title.startsWith('Advance confirmed'));
out.s8 = { title: document.title, h1: document.querySelector('h1').textContent, focus: document.activeElement.textContent, backShown: !!document.querySelector('header button'), text: mainText(), footer: [...document.querySelectorAll('footer button')].map(b => b.innerText) };
out.rowsMatch = JSON.stringify(out.s4Rows.slice(0, 10)) === JSON.stringify(out.s8.text.slice(2, 12));
// late sheet on receipt
btn("What happens if it's late").click(); await tick();
out.sheetOnReceipt = document.querySelector('[role=dialog]')?.getAttribute('aria-labelledby') ? document.querySelector('[role=dialog] h2').textContent : 'missing';
btn('Close').click(); await tick();
// success colour used anywhere?
out.successColourUsed = [...document.querySelectorAll('main *')].some(el => /success/.test(el.className));
btn('Done').click(); await tick();
out.afterDone = document.title;
out

