import { useState } from "react";
import { AppBar, Card, Button, formatAmount } from "../novakit";
import { formatDate, formatTime } from "../advance/salaryAdvance";
import { AdvanceSummary, LateLine, LateSheet } from "./advanceParts";

/**
 * S8: the receipt, right after a successful accept.
 * Everything shown comes from `advance` (acceptTerms), and the rows are the same ones the
 * accept screen showed (principle 1). No back: the advance has been accepted.
 * No celebration and no success colour: neutral surfaces and brand only.
 *
 * New on the receipt: the date it was accepted, the permission in the past tense, and where
 * the record is kept (a placeholder: that's still an open question).
 */
export default function Receipt({ Frame, advance, onDone }) {
  const [lateOpen, setLateOpen] = useState(false);

  const due = formatDate(advance.due_date);
  const time = formatTime(advance.collection.time);
  const until = formatDate(advance.permission.ends_by);

  return (
    <Frame
      title="Advance confirmed: NovaPay"
      appBar={<AppBar title="Advance confirmed" />}
      sheet={<LateSheet open={lateOpen} onClose={() => setLateOpen(false)} due={due} until={until} />}
      actions={<Button onClick={onDone}>Done</Button>}
    >
      <Card className="space-y-2">
        <h2 className="text-title text-neutral-900">
          {formatAmount(advance.disbursed_amount)} is in your NovaPay wallet
        </h2>
        <p className="text-body text-neutral-900">
          You accepted this advance on {formatDate(advance.accepted_on)}. This is what you agreed to.
        </p>
      </Card>

      <AdvanceSummary
        disbursed={advance.disbursed_amount}
        fee={advance.fee}
        total={advance.total}
        due={due}
        time={time}
      />

      <Card className="space-y-2">
        <h2 className="text-body font-semibold text-neutral-900">Your permission</h2>
        <p className="text-body text-neutral-900">
          You allowed NovaPay to take the repayment above automatically. It ends when it's repaid, or on {until} at
          the latest.
        </p>
        <LateLine due={due} time={time} onOpen={() => setLateOpen(true)} />
      </Card>

      <Card className="space-y-2">
        <h2 className="text-body font-semibold text-neutral-900">Your record</h2>
        <p className="text-body text-neutral-900">
          <span className="font-semibold">Placeholder:</span> your copy of this agreement will be kept in [where, to
          be confirmed].
        </p>
      </Card>
    </Frame>
  );
}

