attachment.snippet:
1	import { useState } from "react";
2	import { AppBar, Card } from "../novakit";
3	import { formatDate, formatTime } from "../advance/salaryAdvance";
4	import { AdvanceSummary, LateLine, LateSheet } from "./advanceParts";
5	
6	/**
7	 * The advance's details, opened from its card on the home screen. Not a confirmation (that's
8	 * S8): the terms the person agreed to, in the same rows as the accept screen ("You received"
9	 * instead of "You get"), the permission they gave and when it ends, and what happens if it's
10	 * late. This is where their record of the agreement lives in the app (my Assumption).
11	 * Everything comes from `advance` (acceptTerms).
12	 */
13	export default function AdvanceDetails({ Frame, advance, onBack }) {
14	  const [lateOpen, setLateOpen] = useState(false);
15	
16	  const due = formatDate(advance.due_date);
17	  const time = formatTime(advance.collection.time);
18	  const until = formatDate(advance.permission.ends_by);
19	
20	  return (
21	    <Frame
22	      title="Your salary advance: NovaPay"
23	      appBar={<AppBar title="Your salary advance" onBack={onBack} backLabel="Back to home" />}
24	      sheet={<LateSheet open={lateOpen} onClose={() => setLateOpen(false)} due={due} until={until} />}
25	    >
26	      <AdvanceSummary
27	        disbursed={advance.disbursed_amount}
28	        fee={advance.fee}
29	        total={advance.total}
30	        due={due}
31	        time={time}
32	        received
33	      >
34	        <p className="text-caption text-neutral-700 mt-2">Accepted on {formatDate(advance.accepted_on)}</p>
35	      </AdvanceSummary>
36	
37	      <Card className="space-y-2">
38	        <h2 className="text-body font-semibold text-neutral-900">Your permission</h2>
39	        <p className="text-body text-neutral-900">
40	          You allowed NovaPay to take the repayment above automatically. It ends when it's repaid, or on {until} at
41	          the latest.
42	        </p>
43	      </Card>
44	
45	      <Card className="space-y-2">
46	        <LateLine due={due} time={time} onOpen={() => setLateOpen(true)} />
47	      </Card>
48	    </Frame>
49	  );
50	}

